<?php require 'config/db.php';require_once 'includes/functions.php';client_token();$q=$pdo->prepare("SELECT * FROM blogs WHERE slug=? AND status='published' LIMIT 1");$q->execute([$_GET['slug']??'']);$b=$q->fetch();if(!$b){http_response_code(404);die('Blog not found');}$cq=$pdo->prepare("SELECT * FROM blog_comments WHERE blog_id=? AND status='approved' ORDER BY created_at DESC");$cq->execute([$b['id']]);$comments=$cq->fetchAll();$rq=$pdo->prepare("SELECT reaction,COUNT(*) total FROM blog_reactions WHERE blog_id=? GROUP BY reaction");$rq->execute([$b['id']]);$counts=['like'=>0,'dislike'=>0];foreach($rq as $r)$counts[$r['reaction']]=$r['total'];$page_title=$b['title'];include 'includes/header.php';?><section class="page-hero"><div class="container"><span class="eyebrow"><?=date('d M Y',strtotime($b['published_at']))?></span><h1><?=e($b['title'])?></h1><p class="lead"><?=e($b['excerpt'])?></p></div></section><section class="content-shell"><div class="container"><div class="media-frame"><img src="<?=e($b['image_url'])?>" alt="<?=e($b['title'])?>"></div><div class="form-card" style="margin-top:24px"><div class="blog-detail-body"><?= $b['body'] ?></div><div style="display:flex;gap:10px;margin-top:24px"><button class="btn btn-ghost reaction-btn" data-id="<?=$b['id']?>" data-reaction="like"><i class="fa-regular fa-thumbs-up"></i> Like <span><?=$counts['like']?></span></button><button class="btn btn-ghost reaction-btn" data-id="<?=$b['id']?>" data-reaction="dislike"><i class="fa-regular fa-thumbs-down"></i> Dislike <span><?=$counts['dislike']?></span></button></div></div><div class="split" style="margin-top:26px;align-items:start"><form class="form-card ajax-form" action="api/blog_comment.php" method="post"><input type="hidden" name="blog_id" value="<?=$b['id']?>"><h3>Join the discussion</h3><div class="form-group"><label>Name</label><input class="form-control" name="name" data-required data-message="Tell us your name." placeholder="Your name"></div><div class="form-group"><label>Email</label><input class="form-control" type="email" name="email" data-required placeholder="you@example.com"></div><div class="form-group"><label>Comment</label><textarea class="form-control" name="comment" data-required data-message="Write your comment before submitting." placeholder="Write your comment"></textarea></div><button class="btn btn-primary" type="submit"><i class="fa-solid fa-comment"></i> Post Comment</button></form><div class="form-card"><h3>Comments</h3><?php if(!$comments):?><p class="lead">No comments yet.</p><?php endif;?><?php foreach($comments as $c):?><div style="padding:14px 0;border-bottom:1px solid var(--line)"><b><?=e($c['name'])?></b><p class="lead"><?=e($c['comment'])?></p></div><?php endforeach;?></div></div></div></section><script>$(function(){$('.reaction-btn').on('click',function(){let b=$(this);$.post('api/blog_reaction.php',{blog_id:b.data('id'),reaction:b.data('reaction')}).done(r=>{Toastify({text:r.message,duration:3000,gravity:'top',position:'right'}).showToast();if(r.ok)location.reload()})})})</script><?php include 'includes/footer.php'; ?>